-- Surface finish is independent of the 12-cell solid shell below. These are
-- painted markings on the existing parts, never extruded image slices.
local EGG_FINISH = {
    ['Unicorn Egg']={material=MAT,shine=.02,glow=1},
    ['Kitsune Egg']={material=MAT,shine=0,glow=1},
    ['Night Flame Egg']={material=Enum.Material.Wood,shine=0,glow=1.2},
    ['Archangel Egg']={material=METAL,shine=.06,glow=1.25},
    ['World Burner Egg']={material=Enum.Material.Slate,shine=0,glow=1.15},
    ['Aetheron Egg']={material=METAL,shine=.04,glow=1.2},
    ['Cthulhu Egg']={material=Enum.Material.Slate,shine=0,glow=1.3},
    ['Luminous Cthulhu Egg']={material=Enum.Material.Slate,shine=.01,glow=1.35},
    ['Sabertooth Egg']={material=Enum.Material.Slate,shine=0,glow=1.2},
    ['Skeletal Sabertooth Egg']={material=Enum.Material.Sandstone,shine=0,glow=1.2},
    ['Octophant Egg']={material=Enum.Material.Concrete,shine=0,glow=1.25},
    ['Mecha Scrambler Egg']={material=METAL,shine=.025,glow=1.25},
}

local function finishMaterial(name,c)
    local f=EGG_FINISH[name]
    if name=='Archangel Egg' and math.min(c[1],c[2],c[3])>150 then return MAT,0 end
    if name=='Night Flame Egg' then
        if c[2]>c[1] then return MAT,0 end
        if c[1]>170 and c[2]>95 then return METAL,.035 end
    elseif name=='Octophant Egg' and math.max(c[1],c[2],c[3])<90 then
        return METAL,.02
    end
    return f.material,f.shine
end

local detailCache={}
local function surfaceRows(name)
    if detailCache[name] then return detailCache[name] end
    local spec=EGG_SURFACE[name]
    if not spec then return nil end
    local rows={}
    for y=0,spec[2]-1 do rows[y]={} end
    for _,n in ipairs(spec[4]) do
        local x,y,sx,sy,pi,lit
        x,n=pullBits(n,7) y,n=pullBits(n,7)
        sx,n=pullBits(n,7) sy,n=pullBits(n,7)
        pi,n=pullBits(n,6) lit,n=pullBits(n,1)
        local rect={x,y,sx,sy,pi+1,lit==1}
        for yy=y,y+sy-1 do rows[yy][#rows[yy]+1]=rect end
    end
    local data={spec=spec,rows=rows}
    detailCache[name]=data
    return data
end

local function paintEggBlock(block,name,ix,iy,dw,dh)
    local data=surfaceRows(name)
    if not data then return end
    local spec=data.spec
    local w,h=spec[1],spec[2]
    local x0,x1=ix*w/dw,(ix+1)*w/dw
    -- Legacy geometry counts Y upwards. Reference rows start at the top.
    local y0,y1=(dh-iy-1)*h/dh,(dh-iy)*h/dh
    local seen,clips={},{}
    for y=math.floor(y0),math.min(h-1,math.ceil(y1)-1) do
        for _,r in ipairs(data.rows[y]) do
            if not seen[r] then
                seen[r]=true
                local l,t=math.max(x0,r[1]),math.max(y0,r[2])
                local right,bottom=math.min(x1,r[1]+r[3]),math.min(y1,r[2]+r[4])
                if right>l and bottom>t then
                    clips[#clips+1]={(l-x0)/(x1-x0),(t-y0)/(y1-y0),
                        (right-l)/(x1-x0),(bottom-t)/(y1-y0),r[5],r[6]}
                end
            end
        end
    end
    for _,face in ipairs({Enum.NormalId.Front,Enum.NormalId.Back}) do
        local layers={}
        for _,r in ipairs(clips) do
            local lit=r[6]
            local key=lit and 'Glow' or 'Paint'
            local gui=layers[key]
            if not gui then
                gui=Instance.new('SurfaceGui')
                gui.Name='SAE_'..key
                gui.Face=face
                gui.SizingMode=Enum.SurfaceGuiSizingMode.FixedSize
                gui.CanvasSize=Vector2.new(128,128)
                gui.MaxDistance=120
                gui.AlwaysOnTop=false
                gui.LightInfluence=lit and 0 or 1
                gui.Brightness=lit and EGG_FINISH[name].glow or 1
                gui.ZOffset=0
                gui.ClipsDescendants=true
                gui.Active=false
                gui.Parent=block
                layers[key]=gui
            end
            local c=spec[3][r[5]]
            local mark=Instance.new('Frame')
            mark.Name=lit and 'EmissiveMark' or 'SurfaceMark'
            mark.BorderSizePixel=0
            mark.BackgroundColor3=rgb(c[1],c[2],c[3])
            mark.Position=UDim2.fromScale(r[1],r[2])
            mark.Size=UDim2.fromScale(r[3],r[4])
            mark.Active=false
            mark.Parent=gui
        end
    end
end

local function buildVox(name)
    local spec = VOX[name]
    if not spec then return nil end
    local pal, nums = spec[4], spec[5]
    local color = {}
    local minX, maxX, minY, maxY = 999, -1, 999, -1
    for i = 1, #nums do
        local n = nums[i]
        local x, y, z, sx, sy, sz, pi
        x, n = pullBits(n, 6)
        y, n = pullBits(n, 6)
        z, n = pullBits(n, 4)
        sx, n = pullBits(n, 6)
        sy, n = pullBits(n, 6)
        sz, n = pullBits(n, 4)
        pi, n = pullBits(n, 6)
        local c = pal[pi + 1]
        if c then
            for yy = y, y + sy - 1 do
                for xx = x, x + sx - 1 do
                    local k = xx .. ',' .. yy
                    local prev = color[k]
                    if not prev or z < prev[5] then
                        color[k] = {c[1], c[2], c[3], c[4], z}
                    end
                    if xx < minX then minX = xx end
                    if xx > maxX then maxX = xx end
                    if yy < minY then minY = yy end
                    if yy > maxY then maxY = yy end
                end
            end
        end
    end
    if maxX < minX then return nil end
    local W, H = maxX - minX + 1, maxY - minY + 1
    local function gid(x, y) return (y - minY) * W + (x - minX) + 1 end
    local grid = {}
    for y = minY, maxY do
        for x = minX, maxX do
            local c = color[x .. ',' .. y]
            if c then grid[gid(x, y)] = c end
        end
    end
    local function occ(x, y)
        if x < minX or x > maxX or y < minY or y > maxY then return false end
        return grid[gid(x, y)] ~= nil
    end
    local function dark(c) return math.max(c[1], c[2], c[3]) < 22 end
    for _ = 1, 2 do
        local kill = {}
        for y = minY, maxY do
            for x = minX, maxX do
                local c = grid[gid(x, y)]
                if c and dark(c) and (not occ(x - 1, y) or not occ(x + 1, y) or not occ(x, y - 1) or not occ(x, y + 1)) then
                    kill[#kill + 1] = gid(x, y)
                end
            end
        end
        for _, i2 in ipairs(kill) do grid[i2] = nil end
    end
    local long = math.max(W, H)
    local DH = math.max(8, math.floor(H * 12 / long + 0.5))
    local DW = math.max(6, math.floor(W * 12 / long + 0.5))
    local buckets = {}
    for y = minY, maxY do
        local iy = math.clamp(math.floor((y - minY) * DH / H), 0, DH - 1)
        for x = minX, maxX do
            local c = grid[gid(x, y)]
            if c then
                local ix = math.clamp(math.floor((x - minX) * DW / W), 0, DW - 1)
                local k = iy * DW + ix
                local b = buckets[k]
                if not b then b = {} buckets[k] = b end
                b[#b + 1] = c
            end
        end
    end
    local small = {}
    for iy = 0, DH - 1 do
        small[iy] = {}
        for ix = 0, DW - 1 do
            local b = buckets[iy * DW + ix]
            if b then
                local tally, best, bn = {}, nil, 0
                for _, c in ipairs(b) do
                    local q = math.floor(c[1] / 16) .. ',' .. math.floor(c[2] / 16) .. ',' .. math.floor(c[3] / 16) .. ',' .. c[4]
                    tally[q] = (tally[q] or 0) + 1
                    if tally[q] > bn then bn = tally[q] best = q end
                end
                local qr, qg, qb, qn = best:match('^(%d+),(%d+),(%d+),(%d+)$')
                qr, qg, qb, qn = tonumber(qr), tonumber(qg), tonumber(qb), tonumber(qn)
                local rs, gs, bs, n = 0, 0, 0, 0
                for _, c in ipairs(b) do
                    if math.floor(c[1] / 16) == qr and math.floor(c[2] / 16) == qg and math.floor(c[3] / 16) == qb and c[4] == qn then
                        rs += c[1] gs += c[2] bs += c[3] n += 1
                    end
                end
                small[iy][ix] = {math.floor(rs / n + 0.5), math.floor(gs / n + 0.5), math.floor(bs / n + 0.5), qn}
            end
        end
    end
    local total, neonTally = 0, {}
    for iy = 0, DH - 1 do
        for ix = 0, DW - 1 do
            local c = small[iy][ix]
            if c then
                total += 1
                if c[4] == 1 then
                    local q = c[1] .. ',' .. c[2] .. ',' .. c[3]
                    neonTally[q] = (neonTally[q] or 0) + 1
                end
            end
        end
    end
    if total == 0 then return nil end
    local cols = {}
    local maxHz = 0.55
    local minIX, maxIX, minIY, maxIY = 999, -1, 999, -1
    for iy = 0, DH - 1 do
        local ix = 0
        while ix < DW do
            if not small[iy][ix] then
                ix += 1
            else
                local L = ix
                while ix < DW and small[iy][ix] do ix += 1 end
                local R = ix - 1
                local mid = (L + R) / 2
                local rad = (R - L + 1) / 2
                for x = L, R do
                    local hz = math.sqrt(math.max(0, rad * rad - (x - mid) * (x - mid)))
                    if hz < 0.55 then hz = 0.55 end
                    if hz > maxHz then maxHz = hz end
                    local c = small[iy][x]
                    local q = c[1] .. ',' .. c[2] .. ',' .. c[3]
                    local neon = c[4] == 1 and neonTally[q] and (neonTally[q] / total) <= 0.14
                    cols[#cols + 1] = {x, iy, hz, c, neon}
                    if x < minIX then minIX = x end
                    if x > maxIX then maxIX = x end
                    if iy < minIY then minIY = iy end
                    if iy > maxIY then maxIY = iy end
                end
            end
        end
    end
    if #cols == 0 then return nil end
    local longest = math.max(maxIX - minIX + 1, maxIY - minIY + 1, maxHz * 2)
    local stud = 2.8 / longest
    local m = Instance.new('Model')
    m.Name = name
    local cx = (minIX + maxIX) / 2
    local cy = (minIY + maxIY) / 2
    local root = part(m, 'Core', Vector3.new(stud, stud, stud), rgb(255, 255, 255), CFrame.new(), MAT, 1)
    root.CanQuery = false
    for i = 1, #cols do
        local col = cols[i]
        local px = (col[1] - cx) * stud
        local py = (col[2] - cy) * stud
        local depth = math.max(stud, col[3] * 2 * stud)
        local c = col[4]
        local material,shine = finishMaterial(name,c)
        -- A solid column occupies the exact union of the original body and
        -- neon front segment. Paint changes appearance, never its dimensions.
        local block=part(m,'Shell',Vector3.new(stud,stud,depth),rgb(c[1],c[2],c[3]),CFrame.new(px,py,0),material)
        block.Reflectance=shine
        block.CastShadow=false
        paintEggBlock(block,name,col[1],col[2],DW,DH)
        if i % 8 == 0 then task.wait() end
    end
    m:SetAttribute('SAE_REFERENCE_DETAIL',96)
    m:SetAttribute('SAE_APPEARANCE','Reference finishes on original solid shell')
    return finalize(m, root)
end

